<span class="line">              normalWaveRects<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">PIXI<span class="token punctuation">.</span>Rectangle</span><span class="token punctuation">(</span>x<span class="token punctuation">,</span> waveTopY<span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> blueHeight<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
