<span class="line">    <span class="token keyword">const</span> dataArray <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Uint8Array</span><span class="token punctuation">(</span>fftBinCount<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
