<span class="line">        <span class="token keyword">const</span> a1 <span class="token operator">=</span> startOffset <span class="token operator">+</span> <span class="token punctuation">(</span>i <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token operator">*</span> angleStep<span class="token punctuation">;</span></span>
