<span class="line">      <span class="token keyword">if</span> <span class="token punctuation">(</span>audioContext<span class="token punctuation">.</span>state <span class="token operator">===</span> <span class="token string">&#39;suspended&#39;</span><span class="token punctuation">)</span> <span class="token keyword">await</span> audioContext<span class="token punctuation">.</span><span class="token function">resume</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
